pub fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // We'll maintain a half‐open interval [lo, hi) in which we know
    // at least one occurrence of k resides.  Initially, that's [0, v.len()).
    let mut lo = 0;
    let mut hi = v.len();

    while lo < hi {
        // Prevent overflow by computing mid this way
        let mid = lo + (hi - lo) / 2;
        if v[mid] < k {
            // k must be to the right of mid
            lo = mid + 1;
        } else {
            // v[mid] >= k, so k is in [lo, mid]
            hi = mid;
        }
    }

    // At this point lo == hi, and since we know k was in the original slice
    // and we never eliminate all valid positions, lo is a valid index with v[lo] == k.
    lo
}

